const buttonContrast=require('./button-contrast.cjs');const contrastIssues=[];
/* Real local API/DB, disposable guest only. Screenshots never use existing student sessions. */
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');const fs=require('node:fs/promises'),path=require('node:path'),assert=require('node:assert/strict');const {pathToFileURL}=require('node:url');
const base=process.env.SAWTI_TEST_BASE||'http://127.0.0.1:3002';const dest=process.env.SAWTI_THEME_OUTPUT||'/private/tmp/sawti-theme-review';const results=[],errors=[];
const clean=s=>s.replace(/[\u064b-\u065f\u0670\u0640]/g,'').replace(/\s+/g,' ').trim();
async function click(p,text){for(let i=0;i<35;i++){for(const b of await p.getByRole('button').all()){if(await b.isVisible()&&clean(await b.innerText()).includes(text)){await b.click();return}}await p.waitForTimeout(120)}throw Error('Missing button '+text)}
async function shot(p,id){await p.evaluate(()=>document.fonts.ready);await p.waitForTimeout(300);if(process.env.SAWTI_CHECK_CONTRAST==="1")contrastIssues.push(...(await buttonContrast(p)).map(x=>({id,...x})));if(process.env.SAWTI_THEME_NO_SCREENSHOTS==="1")return;await p.screenshot({path:path.join(dest,id+'.png'),fullPage:true});}
async function layout(p,id){for(const width of [390,768,1440]){await p.setViewportSize({width,height:1000});const size=await p.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth}));assert(size.document<=size.viewport+1,`${id} overflow ${width}: ${size.document}`);if(width===390)await shot(p,id+'-mobile');}await p.setViewportSize({width:1440,height:1000});await shot(p,id);results.push({id,status:'PASS',widths:[390,768,1440]});console.log('PASS',id)}
async function test(id,fn){if(process.env.SAWTI_THEME_FILTER&&!process.env.SAWTI_THEME_FILTER.split(',').includes(id))return;try{await fn();results.push({id,status:"PASS"})}catch(e){results.push({id,status:'FAILED',error:e.message});console.log('FAILED',id,e.message)}}
(async()=>{await fs.mkdir(dest,{recursive:true});const b=await chromium.launch({channel:'chrome',headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.on('pageerror',e=>errors.push(e.message));
await p.goto(base);await click(p,'دخول تجريبي');await p.waitForURL('**/dashboard');await p.getByRole('button',{name:'تَخَطَّ الْجَوْلَةَ'}).click();
for(const [route,id] of [['/dashboard','dashboard'],['/skills','skills'],['/skills/speaking','speaking'],['/skills/writing','writing'],['/skills/self-learning','self'],['/writing-games','games'],['/writing-games/treasure-map','treasure-intro'],['/writing-games/diver-pearl','diver-intro'],['/writing-games/balloon','balloon-intro'],['/assessments','results'],['/class-selection','classes'],['/about','about'],['/missing-theme-page','not-found']])await test(id,async()=>{await p.goto(base+route);await p.getByRole('heading').first().waitFor();await layout(p,id)});
await test('speaking-activity',async()=>{await p.goto(base+'/skills/speaking');await p.locator('.speaking-lesson-card').first().click();await click(p,'رحلة بحرية');await layout(p,'speaking-activity')});
await test('writing-workspace',async()=>{await p.goto(base+'/skills/writing');await p.locator('.writing-topic-card').first().click();await p.getByRole('textbox',{name:'مساحة كتابة النص'}).waitFor();await layout(p,'writing-workspace')});
await test('dictation-intro-wheel-question-result',async()=>{await p.goto(base+'/skills/writing');await p.locator('.writing-playground--dictation').click();await layout(p,'dictation-intro');await click(p,'ابدأ الرحلة');await layout(p,'dictation-wheel');const {DICTATION_QUESTIONS:qs}=await import(pathToFileURL(path.resolve('client/src/lib/dictation-data.ts')).href);
for(let i=0;i<qs.length;i++){await click(p,'أدر العجلة');await p.getByText(/اخْتَرِ الْكِتَابَةَ الصَّحِيحَةَ لِلْكَلِمَةِ/).waitFor();const text=await p.locator('body').innerText();const q=qs.find(q=>text.includes(q.hint)&&q.opts.every(opt=>text.includes(opt)));assert(q,'Actual question matches shipped data');if(i===0)await layout(p,'dictation-question');await p.getByRole('button',{name:q.correct,exact:true}).click();await p.getByText(/أَحْسَنْتَ! الْكِتَابَةُ صَحِيحَةٌ/).waitFor();await click(p,'العودة إلى العجلة');}
await p.getByText('أَكْمَلْتَ الرِّحْلَةَ!',{exact:true}).waitFor();await layout(p,'dictation-results');results.push({id:'all-16-dictation-questions',status:'PASS'});console.log('PASS all dictation questions');});
for(const activity of ['اختبر معلوماتك','رتب الكلمات','أكمل الجملة','اسأل بذكاء','أنا المعلم','اكتب ثم حسن','تحدث ثم قيم نفسك'])await test('self-'+activity,async()=>{await p.goto(base+'/skills/self-learning');await click(p,activity);await p.getByText('هَدَفِي الْيَوْمَ',{exact:false}).waitFor();await click(p,'تحسين الإملاء');await click(p,'التالي: أخطط');for(const s of ['أقرأ السؤال جيدا','أفكر قبل الإجابة','أجيب بنفسي','أراجع إجابتي قبل التأكيد'])await click(p,s);await click(p,'تحقق من الترتيب');await click(p,'ابدأ التنفيذ');await layout(p,'self-task-'+['اختبر معلوماتك','رتب الكلمات','أكمل الجملة','اسأل بذكاء','أنا المعلم','اكتب ثم حسن','تحدث ثم قيم نفسك'].indexOf(activity));});
await test('tour-and-survey',async()=>{await p.goto(base+'/dashboard');await click(p,'دليل الاستخدام');await shot(p,'tour-dialog');await click(p,'تخط الجولة');await click(p,'قيم تجربتك');await shot(p,'survey-dialog');await click(p,'إلغاء');results.push({id:'tour-and-survey',status:'PASS'});});
await test('teacher-gate-workspace-edit',async()=>{await p.goto(base+'/teacher');await p.getByLabel('رَمْزُ الدُّخُولِ:').waitFor();await layout(p,'teacher-gate');await p.getByLabel('رَمْزُ الدُّخُولِ:').fill('audit-teacher-local');await p.getByRole('button',{name:'دُخُولٌ',exact:true}).click();await p.getByRole('button',{name:/نَظْرَةٌ عَامَّةٌ/}).waitFor();await layout(p,'teacher-overview');for(const tab of ['الطلاب','التقييمات','الدروس']){await click(p,tab);await layout(p,'teacher-'+clean(tab));}const edit=p.getByRole('button',{name:/تَعْدِيلٌ/}).first();await edit.click();await layout(p,'teacher-edit-dialog');await click(p,'إلغاء');for(const sub of ['الكتابة','التعلم الذاتي','ألعاب الهمزة','رحلة الإملاء']){await click(p,sub);await layout(p,'teacher-content-'+clean(sub));}});
const anonymous=await b.newContext();const a=await anonymous.newPage();await a.goto(base);await a.getByLabel(/بَرِيدُكَ/).waitFor();await layout(a,'login');await click(a,'ليس لديك حساب');await layout(a,'registration');await anonymous.close();
if(process.env.SAWTI_CHECK_CONTRAST==="1"){await fs.writeFile(path.join(dest,'button-contrast.json'),JSON.stringify(contrastIssues,null,2));results.push({id:'button-label-contrast',status:contrastIssues.length?'FAILED':'PASS',issues:contrastIssues.length});}results.push({id:'uncaught-JavaScript-errors',status:errors.length?'FAILED':'PASS',errors});await fs.writeFile(path.join(dest,'results.json'),JSON.stringify(results,null,2));await b.close();process.exitCode=results.some(r=>r.status==='FAILED')?1:0;
})().catch(e=>{console.error(e);process.exit(1)});
